import Foundation

/// Generated by `scripts/gen-buildinfo.sh` before each build.
/// Edit values manually only if running xcodebuild without the script.
enum BuildInfo {
    static let version = "1.5.1"
    static let commit = "f13bc4a"
    static let branch = "main"
    static let date = "2026-05-08 13:22 UTC"

    static var shortLabel: String {
        "v\(version) · \(commit)"
    }
}
